SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=ANY(ARRAY['c74b44da-73e0-4e07-9950-5c1adb74784b']::uuid[]) UNION ALL SELECT 'variants',id::text,to_jsonb(t) FROM catalog.card_variants t WHERE printing_id=ANY(ARRAY['c74b44da-73e0-4e07-9950-5c1adb74784b']::uuid[]) UNION ALL SELECT 'names',id::text,to_jsonb(t) FROM catalog.card_names t WHERE printing_id=ANY(ARRAY['c74b44da-73e0-4e07-9950-5c1adb74784b']::uuid[]) OR variant_id=ANY(ARRAY['ba7421c1-b1ca-4345-ba12-2777c8867b38']::uuid[]) UNION ALL SELECT 'sets',id::text,to_jsonb(t) FROM catalog.sets t WHERE id=ANY(ARRAY['b5ef438a-ddcb-4093-8c9b-572639565af5']::uuid[]) UNION ALL SELECT 'sources',id::text,to_jsonb(t) FROM ingest.sources t WHERE (code IN ('scrydex','pokellector','tcgcollector','pricecharting') OR lower(base_url) LIKE '%pokellector.com%' OR lower(base_url) LIKE '%tcgcollector.com%' OR lower(base_url) LIKE '%pricecharting.com%') UNION ALL SELECT 'assets',id::text,to_jsonb(t) FROM catalog.assets t WHERE printing_id=ANY(ARRAY['c74b44da-73e0-4e07-9950-5c1adb74784b']::uuid[]) OR variant_id=ANY(ARRAY['ba7421c1-b1ca-4345-ba12-2777c8867b38']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['b5ef438a-ddcb-4093-8c9b-572639565af5']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['c74b44da-73e0-4e07-9950-5c1adb74784b']::uuid[]) OR variant_id=ANY(ARRAY['ba7421c1-b1ca-4345-ba12-2777c8867b38']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['c74b44da-73e0-4e07-9950-5c1adb74784b']::uuid[]) OR variant_id=ANY(ARRAY['ba7421c1-b1ca-4345-ba12-2777c8867b38']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['b5ef438a-ddcb-4093-8c9b-572639565af5']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['b5ef438a-ddcb-4093-8c9b-572639565af5']::uuid[])) ORDER BY scope,identity;
